from common import *
from verify import CC
src('igeeks-v3'); dom('c')
I='#include <stdio.h>\n'
def P(body,inc=I): return inc+'int main(void) {\n'+body+'\n    return 0;\n}'
topic('Control Flow & Functions')
M('b','k',"Which header file declares printf?","stdio.h","stdlib.h","string.h","conio.h","stdio.h declares the standard input and output functions such as printf and scanf.")
M('b','k',"Where does execution of a C program begin?","The main function","The first function in the file","The function named start","The first #include","The runtime calls main(), which is the entry point of every hosted C program.")
M('b','k',"Which format specifier prints an int with printf?","%d","%f","%s","%c","%d prints a signed decimal int. %f is for floating point and %s for strings.")
CC('b','o',"What does this program print?",P('    printf("%d\\n", 10 % 4);'),"2","2.5","0","4","The % operator gives the remainder of the division: 10 = 2 × 4 + 2.")
M('b','k',"Which loop always executes its body at least once?","do-while","while","for","None of them","do-while tests its condition after the body.")
CC('b','o',"What does this program print?",P('    int a = 5, b = a++;\n    printf("%d %d\\n", a, b);'),"6 5","5 5","6 6","5 6","a++ yields the old value (5) to b and then increments a to 6.")
CC('b','o',"What does this program print?",P('    printf("%d\\n", 5 > 3);'),"1","true","5","0","Relational expressions in C produce the int 1 for true and 0 for false.")
topic('Arrays & Strings')
M('b','k',"What is the index of the first element of a C array?","0","1","-1","It depends on the array type","C arrays are zero-based, so a[0] is the first element.")
M('b','k',"Which character ends every C string?","'\\0'","'\\n'","' '","'$'","The null character marks the end of a string. A string of n visible characters needs n + 1 bytes.")
CC('b','o',"What does this program print?",P('    printf("%d\\n", \'A\');'),"65","A","41","Error","A character constant has type int in C. printf with %d shows its ASCII code, 65.")
topic('Pointers & Memory')
M('b','k',"Which operator gives the address of a variable?","&","*","->","#","&x is the address of x. * dereferences a pointer.")
CC('b','o',"What does this program print?",P('    int x = 5;\n    int *p = &x;\n    printf("%d\\n", *p);'),"5","The address of x","0","Error","*p reads the value that p points to, which is x.")
CC('b','o',"What does this program print?",P('    printf("%zu\\n", sizeof(char));'),"1","2","4","8","sizeof(char) is 1 by definition, whatever the platform.")
CC('b','o',"What does this program print?",P('    printf("%.2f\\n", 3.14159);'),"3.14","3.15","3.1","3.14159","%.2f rounds to two decimal places.")
topic('Arrays & Strings')
CC('i','o',"What does this program print?",P('    char s[] = "abc";\n    printf("%zu %zu\\n", sizeof(s), strlen(s));','#include <stdio.h>\n#include <string.h>\n'),"4 3","3 3","4 4","3 4","strlen counts the 3 characters. sizeof also counts the terminating '\\0', so it is 4.")
CC('i','o',"What does this program print?",P('    int a[] = {10, 20, 30};\n    int *p = a;\n    printf("%d\\n", *(p + 2));'),"30","20","10","Address","Pointer arithmetic moves in units of the element size, so p + 2 points at a[2].")
topic('Control Flow & Functions')
CC('i','o',"What does this program print?",P('    for (int i = 0; i < 3; i++) printf("%d", counter());','#include <stdio.h>\nint counter(void) {\n    static int n = 0;\n    return ++n;\n}\n'),"123","111","012","000","A static local keeps its value between calls, so it counts 1, 2, 3.")
CC('i','o',"What does this program print?",P('    printf("%d\\n", -7 % 3);'),"-1","1","2","-2","Since C99 the result of % has the sign of the dividend: -7 = (-2) × 3 + (-1).")
topic('Structures & Storage')
CC('i','o',"What does this program print?",P('    unsigned char c = 255;\n    c++;\n    printf("%d\\n", c);'),"0","256","255","-1","Unsigned arithmetic wraps around. 255 + 1 does not fit in 8 bits and becomes 0.")
topic('Pointers & Memory')
CC('i','o',"What does this program print?",P('    printf("%d\\n", (int)3.99);'),"3","4","3.99","3.0","A cast to int truncates towards zero.")
topic('Preprocessor & I/O')
CC('i','o',"What does this program print?",P('    printf("%d\\n", SQ(2 + 1));','#include <stdio.h>\n#define SQ(x) x * x\n'),"5","9","6","Error","The macro is replaced textually: 2 + 1 * 2 + 1 = 5. Writing ((x) * (x)) in the macro would give 9.")
topic('Preprocessor & I/O')
CC('a','o',"What does this program print?",P('    int a[3] = {1, 2, 3};\n    printf("%d\\n", 2[a]);'),"3","2","Error","1","a[2] is defined as *(a + 2), which is the same as *(2 + a), so 2[a] is valid and equals a[2].")
CC('a','o',"What does this program print?",P('    printf("%d\\n", !!5);'),"1","5","0","!5","The first ! turns 5 into 0 and the second turns 0 into 1. It is a way to normalise a value to 0 or 1.")
CC('a','o',"What does this program print?",P('    int x = 0;\n    if (x = 5) printf("yes");\n    else printf("no");'),"yes","no","Compile error","Nothing","x = 5 is an assignment, not a comparison. Its value is 5, which is true.")
CC('a','o',"What does this program print?",P('    printf("%d\\n", 1 << 3 | 1);'),"9","8","16","4","The shift happens first: 1 << 3 = 8, and 8 | 1 = 9.")
CC('a','o',"What does this program print?",P('    printf("%d\\n", ~5);'),"-6","-5","5","0","On a two's complement machine ~x equals -x - 1, so ~5 is -6.")
CC('a','o',"What does this program print?",P('    printf("%d\\n", 5 & 3 ^ 1);'),"0","1","4","6","& has higher precedence than ^. (5 & 3) = 1, and 1 ^ 1 = 0.")
CC('a','o',"On a typical platform with a 4-byte int, what does this program print?",P('    struct S { char a; int b; };\n    printf("%zu\\n", sizeof(struct S));'),"8","5","4","6","The int must be aligned to 4 bytes, so 3 padding bytes follow the char. The total is 8.")
M('a','k',"What does the following declaration mean? const int *p;","p points to an int that cannot be changed through p","p is a constant pointer to an int","Both the pointer and the int are constant","p can only be assigned once","const int *p is a pointer to const int. int *const p would be a const pointer to a modifiable int.")
M('a','k',"What does the volatile qualifier tell the compiler?","The value may change outside the program's control, so every access must really be made","The value is stored in a register","The value can never change","The variable is local to the function","Volatile is used for hardware registers and variables changed by signal handlers.")
M('a','k',"A function returns the address of one of its local variables. What is the problem?","The memory is gone after the function returns, so using the pointer is undefined behaviour","The compiler will refuse to compile it","The value is automatically copied to the heap","It leaks memory","Local variables live on the stack and are invalid after the call. This is a dangling pointer.")
M('a','k',"When must memmove be used instead of memcpy?","When the source and destination memory areas may overlap","When copying strings","When copying more than 1 KB","When the data is not aligned","memcpy has undefined behaviour for overlapping regions. memmove handles overlap correctly.")
M('a','k',"What is the result of calling free on the same pointer twice?","Undefined behaviour (often heap corruption)","The second call is ignored safely","A compile error","The program exits with an error code","Setting the pointer to NULL after free makes a second free(NULL) harmless.")
M('a','k',"What happens when a signed int overflows in C?","The behaviour is undefined","It wraps around to the minimum value","The program is terminated","The result is saturated at INT_MAX","Unsigned overflow wraps, but signed overflow is undefined, and compilers may assume it never happens.")
M('a','k',"What is wrong with this: char *s = \"hello\"; s[0] = 'H';","Modifying a string literal is undefined behaviour","Nothing, it is valid","char* cannot point to a string","The literal is stored in a register","String literals may be placed in read-only memory. Use char s[] = \"hello\"; for a modifiable copy.")
M('a','k',"What does the restrict qualifier promise?","That for the lifetime of the pointer, only it (or values derived from it) accesses that object","That the pointer is not NULL","That the pointer is read-only","That the pointer is aligned","The promise lets the compiler optimise more aggressively. Breaking it is undefined behaviour.")
topic('Control Flow & Functions')
CC('i','o',"What does this program print?",P('    int x = 10;\n    printf("%d\\n", x / 3 * 3);'),"9","10","3","10.0","Integer division truncates: 10 / 3 = 3, and 3 * 3 = 9. Operators of equal precedence are evaluated left to right.")
